/* V24 — توسيع الأسماء الجامدة/غير العاقلة الشائعة: يمنحها معرفةً صرفيةً ودلالية
   (animacy) فيعمل لها التحليلُ وحكمُ المفعول به («شرب الماء»، «شاهد الفيلم») معًا.
   إضافة صرفة لا تُغيّر مخرجاتٍ قائمة. */
function expandedNounLemmasV24() {
  const out = {};
  const addM = (lemma, plural, animacy = 'nonhuman') => {
    out[lemma] = {gender: 'm', animacy, forms: [
      form(lemma, 'sg'),
      form(lemma + 'ان', 'du', 'nominative'), form(lemma + 'ين', 'du', 'accgen'),
      form(plural, 'pl', null, {pluralType: 'broken'})
    ]};
  };
  const addF = (lemma, plural, animacy = 'nonhuman') => {
    const stem = lemma.endsWith('ة') ? lemma.slice(0, -1) : lemma;
    out[lemma] = {gender: 'f', animacy, forms: [
      form(lemma, 'sg'),
      form(stem + 'تان', 'du', 'nominative'), form(stem + 'تين', 'du', 'accgen'),
      form(plural || (stem + 'ات'), 'pl', null, plural ? {pluralType: 'broken'} : {})
    ]};
  };
  // مأكولات/مشروبات (جامدة — لا يمكن أن تكون فاعلًا لأفعالها)
  addM('حليب', 'ألبان', 'mass'); addM('شاي', 'شايات', 'mass'); addM('عصير', 'عصائر', 'mass');
  addF('قهوة', 'قهوات', 'mass'); addM('طعام', 'أطعمة', 'mass'); addM('خبز', 'أخباز', 'mass');
  addM('لحم', 'لحوم', 'mass'); addM('سكر', 'سكر', 'mass'); addM('ملح', 'أملاح', 'mass');
  addM('زيت', 'زيوت', 'mass'); addM('عسل', 'عسل', 'mass');
  // أشياء/أدوات
  addM('فيلم', 'أفلام'); addM('حقل', 'حقول'); addM('أرض', 'أراض', 'nonhuman');
  addM('بيت', 'بيوت'); addM('طريق', 'طرق'); addM('قلم', 'أقلام');
  addM('باب', 'أبواب'); addM('مفتاح', 'مفاتيح'); addM('هاتف', 'هواتف');
  addM('حاسوب', 'حواسيب'); addM('ورق', 'أوراق', 'mass'); addM('قميص', 'قمصان');
  addM('حذاء', 'أحذية'); addM('قبعة', 'قبعات'); addM('نظارة', 'نظارات');
  addF('سلطة', 'سلطات'); addF('فاكهة', 'فواكه'); addF('خضروات', 'خضروات');
  addF('شطيرة', 'شطائر'); addF('قصة', 'قصص'); addF('مجلة', 'مجلات');
  addF('رسالة', 'رسائل'); addF('هدية', 'هدايا'); addF('لعبة', 'ألعاب');
  addF('حقيبة', 'حقائب'); addF('مظلة', 'مظلات'); addF('لوحة', 'لوحات');
  addF('طاولة', 'طاولات'); addF('خزانة', 'خزائن'); addF('غرفة', 'غرف');
  addF('أريكة', 'أرائك'); addF('شاشة', 'شاشات'); addF('طابعة', 'طابعات');
  addF('شحنة', 'شحنات'); addF('ضربة', 'ضربات'); addF('صفحة', 'صفحات');
  addF('عجلة', 'عجلات'); addF('دراجة', 'دراجات'); addF('سفينة', 'سفن');
  addM('سرير', 'أسرّة'); addM('دفتر', 'دفاتر'); addM('كرسي', 'كراسي');
  addM('لوح', 'ألواح'); addM('مقعد', 'مقاعد'); addM('قميص', 'قمصان');
  addM('معطف', 'معاطف'); addM('سروال', 'سراويل'); addM('جورب', 'جوارب');
  addM('زجاج', 'أزجاج', 'mass'); addM('ورق', 'أوراق', 'mass');
  // «أرض» مؤنثةٌ غيرُ عاقلة (جمعُها أراضٍ) — تُحسمُ جنسُها فتُحفظ «الأرض واسعة».
  out['أرض'] = {gender: 'f', animacy: 'nonhuman', forms: [
    form('أرض', 'sg'), form('أرضان', 'du', 'nominative'), form('أرضين', 'du', 'accgen'),
    form('أراض', 'pl', null, {pluralType: 'broken'}), form('أراضٍ', 'pl', null, {pluralType: 'broken'})
  ]};
  return out;
}

