function regularAdjectiveParadigm(lemma) {
  const f = `${lemma}ة`;
  return {
    mSg: lemma, fSg: f,
    mDuNom: `${lemma}ان`, mDuObl: `${lemma}ين`,
    fDuNom: `${lemma}تان`, fDuObl: `${lemma}تين`,
    mPlNom: `${lemma}ون`, mPlObl: `${lemma}ين`, fPl: `${lemma}ات`
  };
}

