/* V24 — توسعة صفات شائعة ناقصة كانت تحرم المحركَ من إملائها («غزيره»←غزيرة)
   ونحوها («أصبح الجو بارد»←باردًا). إضافة صرفة لا تُغيّر قواعدَ قائمة. */
function expandedAdjectiveLemmasV24() {
  const lemmas = [
    // صفات الجوّ والطقس
    'بارد', 'حار', 'جاف', 'رطب', 'معتدل', 'غائم', 'ماطر', 'عاصف', 'شديد',
    'دافئ', 'مشمس', 'صاف', 'قائظ', 'بارد',
    // صفات الكمية والحجم
    'غزير', 'وفير', 'شاسع', 'فسيح', 'هائل', 'ضخم', 'ضئيل', 'نزر',
    // صفات حسية ومعنوية
    'لذيذ', 'مقرمش', 'طازج', 'فاسد', 'عذب', 'مالح', 'حلو', 'مر',
    'ناصع', 'باهت', 'فاتح', 'داكن', 'زاهي',
    // صفات سلوكية/أخلاقية
    'متعاون', 'مسؤول', 'جاد', 'مرن', 'صلب', 'لين', 'عنيد', 'وديع',
    'غليظ', 'رقيق', 'صريح', 'متحفظ', 'سخي', 'بخيل', 'شجاع',
    // صفات أداء/حالة
    'ناجز', 'عاجز', 'ميسور', 'عسير', 'يمن', 'عاصم', 'نافذ', 'فعال',
    'مجد', 'مجد', 'ناضج', 'سليم', 'معافى', 'مريض'
  ];
  // إزالة التكرار مع الحفاظ على الترتيب
  const seen = new Set();
  const uniq = lemmas.filter(l => !seen.has(l) && seen.add(l));
  // صفات الحال الشائعة (عاد منتصرًا/مبتسمًا/سعيدًا...) — كانت ناقصةً فتفوت
  // حالُ النصبِ بعد أفعال الحركة.
  uniq.push('منتصر', 'مبتسم', 'سعيد', 'حزين', 'غاضب', 'متعجل', 'متردد',
    'واقف', 'جالس', 'قائم', 'ماشي', 'مستعجل', 'متعب', 'مرهق', 'مندهش',
    'متفائل', 'متشائم', 'خائف', 'فرح', 'حزين');
  // إزالة أي تكرار
  const seen2 = new Set();
  const uniq2 = uniq.filter(l => !seen2.has(l) && seen2.add(l));
  return Object.fromEntries(uniq2.map(lemma => [lemma, regularAdjectiveParadigm(lemma)]));
}

