  for (const [, text] of V1910_BLOCK_REGRESSIONS) controls.push(text);
  for (const text of V1910_OVER_CORRECTION_CORPUS) controls.push(text);
  for (const [id, text] of NO_FALSE_POSITIVE_CORPUS) controls.push(text);

