/* ── تشغيل معيار V24 الإضافي على محرك موجود ── */
/* V24 — معالجة النصوص الطويلة جدًا (batching): يقسّم النص إلى مقاطع عند فواصل
   الجمل، يعالج كل مقطع بتحليلٍ مستقل، ثم يدمج النتائج مع إعادة ضبط المواضع إلى
   إحداثيات النص الأصلي. يخفّف ضغطَ محللِ الجمل على النصوص الضخمة (مئات الأسطر)
   ويحدّ من ذروة الاستهلاك، مع الحفاظ على صحة المواضع والتقارير. */
function analyzeLongV24(input, options = {}) {
  const merged = {batchSize: 4000, ...options};
  const text = String(input ?? '');
  const opts = {...merged};
  delete opts.batchSize;
  if (text.length <= (merged.batchSize || 4000)) return analyze(text, opts);

  // تقسيم عند فواصل الجمل (نقطة/علامة استفهام/تعجب/نقطة سطر جديدة) إلى مقاطع
  // لا تتجاوز العتبة — يُقسم فعليًا عند أول فاصل بعد بلوغ العتبة.
  const parts = [];
  const reGlobal = /[.!؟؟\u061F؛\n]\s*/gu;
  let last = 0;
  const threshold = merged.batchSize || 4000;
  let m;
  let segStart = 0;
  while ((m = reGlobal.exec(text))) {
    const segEnd = m.index + m[0].length;
    if (segEnd - segStart >= threshold) {
      parts.push({start: segStart, end: segEnd, text: text.slice(segStart, segEnd)});
      segStart = segEnd;
    }
  }
  if (segStart < text.length) parts.push({start: segStart, end: text.length, text: text.slice(segStart)});
  if (parts.length <= 1) return analyze(text, opts);

  // معالجة كل مقطع وجمع الملاحظات مع تعديل المواضع
  const allFindings = [];
  let corrected = '';
  let offset = 0;
  const rawCorrected = [];
  for (const part of parts) {
    const r = analyze(part.text, opts);
    const shift = part.start;
    for (const f of (r.findings || [])) {
      f.index = (f.index || 0) + shift;
      if (f.normalizedIndex != null) f.normalizedIndex += shift;
    }
    allFindings.push(...(r.findings || []));
    rawCorrected.push(r.corrected);
  }
  const combinedCorrected = rawCorrected.join('');
  const result = analyze(text, {...opts, maxFindings: 0});
  // إعادة بناء النتيجة على أساس المعالجة المجزأة
  result.original = text;
  result.corrected = combinedCorrected;
  result.findings = allFindings;
  result.errors = allFindings;
  result.suggestions = allFindings.filter(x => !x.autoCorrectable);
  result.manualReview = allFindings.filter(x => !x.autoCorrectable);
  result.autoCorrectable = allFindings.filter(x => x.autoCorrectable);
  result.batched = true;
  result.batchCount = parts.length;
  result.performance = {timeMs: performanceNowV24() - (result.performance?.startMs || performanceNowV24()),
    characters: text.length, findings: allFindings.length};
  return result;
}

function runV24AdditionBenchmarkV24(engine = {analyze}, options = {}) {
  const rows = [];
  let errCaught = 0, fp = 0, totalErr = 0, totalCtl = 0;
  for (const t of V24_BENCHMARK_ADDITIONS) {
    const res = engine.analyze(t.text, options);
    const repls = res.findings.map(f => f.replacement).filter(Boolean);
    const isProtect = t.replacements.length === 0;
    const lang = (res.findings || []).filter(f => f.classification !== 'style' && f.suggestionGroup !== 'تحسين التنسيق والأسلوب');
    if (isProtect) {
      totalCtl += 1;
      if (lang.length) fp += 1;
      rows.push({id: t.category, text: t.text, type: 'protect', ok: lang.length === 0,
        findings: lang.map(f => f.original + '→' + f.replacement)});
    } else {
      totalErr += 1;
      const hit = t.replacements.some(exp => repls.some(r => r.includes(exp) || exp.includes(r)));
      if (hit) errCaught += 1;
      rows.push({id: t.category, text: t.text, type: 'error', ok: hit,
        expected: t.replacements, got: repls});
    }
  }
  return {
    version: META.version, total: V24_BENCHMARK_ADDITIONS.length,
    errors: totalErr, controls: totalCtl,
    caught: errCaught, falsePositives: fp,
    recall: totalErr ? errCaught / totalErr : 1,
    precision: totalErr ? errCaught / (errCaught + fp) : 1,
    valid: fp === 0 && errCaught === totalErr,
    rows
  };
}




/* ==========================================================================\n * V25.0.0 PRO FINAL — CENTRAL DECISION ENGINE\n * --------------------------------------------------------------------------\n * السياسة: additive + root-cause + backward-compatible.\n * القواعد القديمة تولّد المرشحين؛ هذه الطبقة وحدها تحسم ما يظهر وما يُطبَّق.\n * ========================================================================== */
/* V25.0.1 precision-first hardening:
 * - no implicit-mood promotion without an explicit governor proof
 * - standalone «لي» is not a jussive marker
 * - dependent masculine sound-plural agreement is resolved from the head
 * - structural alternative repairs are withheld instead of guessed
 * - overlapping candidate spans are conflict-resolved, not independently applied
 * - benchmark auto-correction precision is measured on exact end-to-end golds
 */
const V25_VERSION = '25.4.1';
const V25_DECISION_TIERS = Object.freeze({
  CERTAIN: 0.995,
  HIGH: 0.975,
  REVIEW: 0.900,
  ABSTAIN: 0.750
});

function v25IsProtected(context, start, length){
  const end=start+length;
  return (context.protectedSpans||[]).some(sp => {
    const a=Number(sp.start ?? sp.index ?? sp.begin ?? -1);
    const b=Number(sp.end ?? (a+Number(sp.length||0)));
    return a>=0 && b>start && a<end;
  });
}
function v25ClearQuestionAtStart(text, dotIndex){
  const before=String(text).slice(0,dotIndex);
  const m=/(?:^|[.!؟\n]\s*)([^.!؟\n]{1,160})$/u.exec(before);
  if(!m) return false;
  const body=m[1].trim();
  if(!body) return false;
  if(/^(?:هل|متى|أين|كيف|لماذا|ماذا|أي|كم)\s+/u.test(body)) return true;
  if(/^من\s+(?:هو|هي|هم|هن|هذا|هذه|هؤلاء|الذين|التي)\b/u.test(body)) return true;
  // V25.2 — «من» الاستفهامية قبل أداة استفهام أخرى: «من أين أنت»، «من متى».
  if(/^من\s+(?:أين|متى|كيف|لماذا|ماذا|كم|من|ما)\b/u.test(body) && !/^من\s+(?:أجل|خلال|حيث|دون|غير|بين)\b/u.test(body)) return true;
  if(/^من\s+(?:[اأإآ].*?)\s+(?:؟|$)/u.test(body) && !/^من\s+(?:أجل|خلال|حيث|دون|غير|بين)\b/u.test(body)) return true;
  // V25.2 — «ما» الاستفهامية قبل اسم صريح (غالبًا مع ضمير مخاطب): «ما اسمك».
  // لا تنطبق على «ما» النافية/المصدرية قبل الأفعال، ولا على «ما ... إلا».
  if(/^ما\s+(?:اسم|رأي|معنى|خبر|سبب|هدف|فائدة|عدد|لون|حجم|شكل|نوع|وقت|موعد|عنوان|هاتف|رقم|قدر|مقدار|حكم|فرق|شأن|خطب|بال|حال|موضوع|محتوى|مضمون)(?:ك|كِ|ه|ها|هم|هن|كما|كم|كن|نا|ي)?\b/u.test(body) && !/\bإلا\b/u.test(body)) return true;
  // V25.2 — «ما» قبل اسم إشارة بلا «إلا» بعدها: «ما هذا؟».
  if(/^ما\s+(?:هذا|هذه|هذان|هاتان|هؤلاء|ذلك|تلك)\b/u.test(body) && !/\bإلا\b/u.test(body)) return true;
  return false;
}
function v25Finding(context, spec){
  const f=findingFromTextSpan(context,{normalizedStart:spec.start, normalizedEnd:spec.start+spec.length,
    replacement:spec.replacement, ruleId:spec.ruleId, type:spec.type||'إملائي',
    classification:spec.classification||'orthographic', confidence:spec.confidence,
    explanation:spec.explanation, evidence:spec.evidence||[], safe:Boolean(spec.safe),
    metadata:{...(spec.metadata||{}), v25:true, decisionEngine:true}});
  f.original = spec.original ?? f.original;
  return f;
}

